CREATE TABLE sheets_config(id INTEGER PRIMARY KEY CHECK(id=1),version INTEGER NOT NULL DEFAULT 1,config TEXT NOT NULL,verificacion TEXT,validacion TEXT,modificado_por INTEGER REFERENCES usuarios(id),modificado_en TEXT);
CREATE TABLE sheets_estado(documento TEXT NOT NULL,pestana TEXT NOT NULL,clave TEXT NOT NULL,columna TEXT NOT NULL,base REAL NOT NULL DEFAULT 0,ultimo TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,autor INTEGER NOT NULL REFERENCES usuarios(id),nota TEXT NOT NULL,modificado_en TEXT NOT NULL,PRIMARY KEY(documento,pestana,clave,columna));
CREATE TABLE sheets_contribuciones(documento TEXT NOT NULL,pestana TEXT NOT NULL,fecha TEXT NOT NULL,estacion_id INTEGER NOT NULL REFERENCES estaciones(id),movil_id INTEGER NOT NULL REFERENCES moviles(id),jornada_id INTEGER NOT NULL REFERENCES jornadas(id),actividad_id INTEGER NOT NULL REFERENCES actividades(id),cantidad INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,modificado_en TEXT NOT NULL,sincronizado_en TEXT NOT NULL,PRIMARY KEY(documento,pestana,fecha,estacion_id,movil_id,jornada_id,actividad_id));
CREATE TABLE sheets_historial(id INTEGER PRIMARY KEY,usuario_id INTEGER NOT NULL REFERENCES usuarios(id),creado_en TEXT NOT NULL,estacion_id INTEGER NOT NULL REFERENCES estaciones(id),fecha TEXT NOT NULL,movil_id INTEGER NOT NULL REFERENCES moviles(id),jornada_id INTEGER NOT NULL REFERENCES jornadas(id),estado TEXT NOT NULL,registros INTEGER NOT NULL DEFAULT 0,celdas INTEGER NOT NULL DEFAULT 0,detalle TEXT NOT NULL,error TEXT);
CREATE TABLE sheets_previews(id TEXT PRIMARY KEY,usuario_id INTEGER NOT NULL REFERENCES usuarios(id),creado_en TEXT NOT NULL,version INTEGER NOT NULL,datos TEXT NOT NULL,consumido INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sheets_locks(documento TEXT NOT NULL,pestana TEXT NOT NULL,token TEXT NOT NULL,owner_pid INTEGER NOT NULL,creado_en TEXT NOT NULL,PRIMARY KEY(documento,pestana));
